export function getTestBySlug(slug: string): EnglishTest | undefined {
  if (!slug) return undefined;
  const clean = slug.toLowerCase().trim();
  // Normalize aliases
  const aliasMap: Record<string, string> = {
    'ielts-academic': 'ielts',
    'ielts-general': 'ielts',
    'ukvi': 'ielts-ukvi',
    'ielts-for-ukvi': 'ielts-ukvi',
    'selt': 'ielts-ukvi',
    'pte': 'pte-academic',
    'pearson': 'pte-academic',
    'toefl': 'toefl-ibt',
    'toefl-ibt-home': 'toefl-ibt',
    'det': 'duolingo',
    'duolingo-english-test': 'duolingo',
    'oietc-ellt': 'oietc',
    'ellt': 'oietc',
    'oxford-ellt': 'oxford-ellt',
    'oietc': 'oietc',
    'languagecert': 'languagecert',
    'kaplan': 'kaplan',
    'kaplan-english-test': 'kaplan',
    'kite': 'kaplan',
    'cambridge': 'cambridge-english',
    'cae-cpe': 'cambridge-english',
    'c1-advanced': 'cambridge-english',
    'c2-proficiency': 'cambridge-english',
    'cae': 'cambridge-english',
    'cpe': 'cambridge-english',
    'cambridge-english': 'cambridge-english',
    'oet': 'oet',
    'gre': 'gre',
    'gmat': 'gmat',
    'sat': 'sat',
    'act': 'act',
    'moi-guidance': 'moi',
    'moi': 'moi',
    'medium-of-instruction': 'moi',
  };
  const normalized = aliasMap[clean] || clean;
  return ENGLISH_PREP_TESTS.find(t => t.slug === normalized);
}

export function getModulesByTestSlug(slug: string): TestModule[] {
  const test = getTestBySlug(slug);
  if (!test) return [];
  // Use normalized slug for module lookup
  const moduleKey = test.slug;
  return ENGLISH_PREP_MODULES[moduleKey] || ENGLISH_PREP_MODULES[moduleKey.replace('-', '')] || ENGLISH_PREP_MODULES['ielts']?.slice(0,2) || [];
}

export function getFaqsByTestSlug(slug: string): TestFaq[] {
  const test = getTestBySlug(slug);
  if (!test) return [];
  return ENGLISH_PREP_FAQS.filter(f => f.testId === test.id).sort((a,b) => a.sortOrder - b.sortOrder);
}

export function getAcceptanceByTestSlug(slug: string): TestAcceptance[] {
  const test = getTestBySlug(slug);
  if (!test) return [];
  return ENGLISH_PREP_ACCEPTANCE.filter(a => a.testId === test.id);
}

export function getResourcesByTestSlug(slug: string): TestResource[] {
  const test = getTestBySlug(slug);
  if (!test) return [];
  return ENGLISH_PREP_RESOURCES.filter(r => r.testId === test.id);
}
